int wn_sig32_lookup(const char *name, wn_sig32 *out)
{
    for (const sig32_ent *e = sigs; e->name; e++) {
        if (strcmp(e->name, name) == 0) {
            memset(out, 0, sizeof *out);
            out->arity = e->words;
            out->n_double = e->nd;
            out->cleanup = e->vararg ? 0 : e->words;
            out->flags = e->vararg ? WN32_VARARG : 0;
            return 1;
        }
    }
    return 0;
}
